(function () {
  $(function () {
    var auditLogservices = abp.services.app.report;

    var d = new Date(),

      n = d.getMonth() + 1,

      y = d.getFullYear();


    var DashboardForm = {
      _selectMonth: $("#Month"),
      _selectYear: $("#Year"),
      _selectType: $("#Type"),
      _btnSearch: $("#btnSearch"),
      startTime: null,
      endTime: null,
      type: {
        type: null,
        setType: function () {
          var type = DashboardForm._selectType.val();
          if (type == "0") {
            DashboardForm.type.type = 1;
            DashboardForm._selectMonth.show();
          } else {
            DashboardForm._selectMonth.hide();
            DashboardForm.type.type = 2;
          }
          return
        }
      },
      TimeRanges: {
        startTime: null,
        endTime: null,
        setTime: function () {
          DashboardForm.TimeRanges.startTime = new Date(DashboardForm._selectYear.val(), DashboardForm._selectMonth.val() - 1, 1);

          // Lấy ngày cuối cùng của tháng bằng cách lấy ngày 0 của tháng tiếp theo
          DashboardForm.TimeRanges.endTime = new Date(DashboardForm._selectYear.val(), DashboardForm._selectMonth.val(), 0);

          // Đặt thời gian của endTime là cuối ngày (23:59:59)
          DashboardForm.TimeRanges.endTime.setHours(23, 59, 59, 999);
        }
      },
      init: function () {
        DashboardForm._selectMonth.val(n);
        DashboardForm._selectYear.val(y);
        DashboardForm.TimeRanges.setTime();
        DashboardForm.type.setType();
        DashboardForm._btnSearch.click(function () {
          DashboardForm.type.setType();
          DashboardForm.TimeRanges.setTime();
          chartWebsiteAudience.loadChart();
        });
        DashboardForm._selectType.change(function () {
          DashboardForm.type.setType();
        });

      }
    }

    DashboardForm.init();

    var chartWebsiteAudience = {
      utils: {
        merge: (a, b) => Object.assign({}, a, b),
      },
      presets: {
        green: '#00ff00'  // Example color
      },
      options: {
        responsive: true,
        scales: {
          x: {
            beginAtZero: true,
            type: 'time',
            time: {
              unit: 'day'
            }
          },
          y: {
            beginAtZero: true
          }
        },
      },
      loadChart: function () {
       
          // Reset the random seed to generate the same data for all charts
          auditLogservices.getReportVisitView({ type: DashboardForm.type.type, startTime: DashboardForm.TimeRanges.startTime, endTime: DashboardForm.TimeRanges.endTime }).done(function (result) {
            const labels = result.items.map(item => item.visitTime);
            const data = result.items.map(item => item.totalVisit);
            chartData = { labels, data };
            new Chart('chart-2' , {
              type: 'line',
              data: {
                labels: chartData.labels,
                datasets: [{
                  /* backgroundColor: utils.transparentize(presets.green),*/
                  borderColor: chartWebsiteAudience.presets.green,
                  data: chartData.data,
                  label: 'Total Visits',
                  fill: "Tổng view"
                }]
              },
              options: chartWebsiteAudience.utils.merge(chartWebsiteAudience.options, {
                plugins: {
                  legend: {
                    display: true,
                    position: 'top'
                  },
                  title: {
                    fill: "Tổng view",
                    display: true
                  }
                }
              })
            });
          })
          // Extract data for chart
      },
      init: function () {
        chartWebsiteAudience.loadChart();
      }
    }
    chartWebsiteAudience.init();
  });
})();